//! Row conversion for offline models.

use fundamental_core::model::OfflineModel;

use crate::db::{OfflineDbError, Row, Value};

/// Row conversion for offline models.
///
/// Generated by `#[derive(Model)] #[model(offline)]`.
pub trait OfflineRecord: OfflineModel + Sized {
    /// The primary key column name (the `#[model(id)]` field's column).
    fn primary_key_column() -> &'static str;

    /// Converts the model into column values, aligned with [`OfflineModel::column_names`].
    fn to_values(&self) -> Vec<Value>;

    /// Reconstructs the model from a row; non-source locales are applied by
    /// [`apply_translation`](Self::apply_translation).
    #[expect(clippy::missing_errors_doc, reason = "readability baseline")]
    fn from_row(row: &Row) -> Result<Self, OfflineDbError>;

    /// The companion-table rows for this record's translatable fields.
    fn translation_rows(&self) -> Vec<fundamental_core::i18n::TranslationRow> {
        Vec::new()
    }

    /// Puts one companion-table row on its translatable field; a no-op otherwise.
    fn apply_translation(&mut self, row: fundamental_core::i18n::TranslationRow) {
        let _ = row;
    }
}
